36	/// Directed acyclic graph of expressions.
37	/// This is an intermediate representation of actions which is usually built from expression list AST.
38	/// Node of DAG describe calculation of a single column with known type, name, and constant value (if applicable).
39	///
40	/// DAG representation is useful in case we need to know explicit dependencies between actions.
41	/// It is helpful when it is needed to optimize actions, remove unused expressions, compile subexpressions,
42	/// split or merge parts of graph, calculate expressions on partial input.
43	///
44	/// Built DAG is used by ExpressionActions, which calculates expressions on block.
45	class ActionsDAG
46	{
47	public:
48	
49	    enum class ActionType
50	    {
51	        /// Column which must be in input.
52	        INPUT,
53	        /// Constant column with known value.
54	        COLUMN,
55	        /// Another one name for column.
56	        ALIAS,
57	        /// Function arrayJoin. Specially separated because it changes the number of rows.
58	        ARRAY_JOIN,
59	        FUNCTION,
60	    };
61	
62	    struct Node;
63	    using NodeRawPtrs = std::vector<Node *>;
64	    using NodeRawConstPtrs = std::vector<const Node *>;
65	
66	    struct Node
67	    {
68	        NodeRawConstPtrs children;
69	
70	        ActionType type{};
71	
72	        std::string result_name;
73	        DataTypePtr result_type;
74	
75	        FunctionOverloadResolverPtr function_builder;
76	        /// Can be used after action was added to ExpressionActions if we want to get function signature or properties like monotonicity.
77	        FunctionBasePtr function_base;
78	        /// Prepared function which is used in function execution.
79	        ExecutableFunctionPtr function;
80	        /// If function is a compiled statement.
81	        bool is_function_compiled = false;
82	        /// It is deterministic (See IFunction::isDeterministic).
83	        /// This property is kept after constant folding of non-deterministic functions like 'now', 'today'.
84	        bool is_deterministic = true;
85	
86	        /// For COLUMN node and propagated constants.
87	        ColumnPtr column;
88	
89	        void toTree(JSONBuilder::JSONMap & map) const;
90	    };
91	
92	    /// NOTE: std::list is an implementation detail.
93	    /// It allows to add and remove new nodes inplace without reallocation.
94	    /// Raw pointers to nodes remain valid.
95	    using Nodes = std::list<Node>;
96	
97	private:
98	    Nodes nodes;
99	    NodeRawConstPtrs index;
100	    NodeRawConstPtrs inputs;
101	
102	    bool project_input = false;
103	    bool projected_output = false;
104	
105	public:
106	    ActionsDAG() = default;
107	    ActionsDAG(ActionsDAG &&) = default;
108	    ActionsDAG(const ActionsDAG &) = delete;
109	    ActionsDAG & operator=(const ActionsDAG &) = delete;
110	    explicit ActionsDAG(const NamesAndTypesList & inputs_);
111	    explicit ActionsDAG(const ColumnsWithTypeAndName & inputs_);
112	
113	    const Nodes & getNodes() const { return nodes; }
114	    const NodeRawConstPtrs & getIndex() const { return index; }
115	    const NodeRawConstPtrs & getInputs() const { return inputs; }
116	
117	    NamesAndTypesList getRequiredColumns() const;
118	    Names getRequiredColumnsNames() const;
119	    ColumnsWithTypeAndName getResultColumns() const;
120	    NamesAndTypesList getNamesAndTypesList() const;
121	
122	    Names getNames() const;
123	    std::string dumpNames() const;
124	    std::string dumpDAG() const;
125	
126	    const Node & addInput(std::string name, DataTypePtr type);
127	    const Node & addInput(ColumnWithTypeAndName column);
128	    const Node & addColumn(ColumnWithTypeAndName column);
129	    const Node & addAlias(const Node & child, std::string alias);
130	    const Node & addArrayJoin(const Node & child, std::string result_name);
131	    const Node & addFunction(
132	            const FunctionOverloadResolverPtr & function,
133	            NodeRawConstPtrs children,
134	            std::string result_name);
135	
136	    /// Index can contain any column returned from DAG.
137	    /// You may manually change it if needed.
138	    NodeRawConstPtrs & getIndex() { return index; }
139	    /// Find first column by name in index. This search is linear.
140	    const Node & findInIndex(const std::string & name) const;
141	    /// Same, but return nullptr if node not found.
142	    const Node * tryFindInIndex(const std::string & name) const;
143	    /// Find first node with the same name in index and replace it.
144	    /// If was not found, add node to index end.
145	    void addOrReplaceInIndex(const Node & node);
146	
147	    /// Call addAlias several times.
148	    void addAliases(const NamesWithAliases & aliases);
149	    /// Add alias actions and remove unused columns from index. Also specify result columns order in index.
150	    void project(const NamesWithAliases & projection);
151	
152	    /// If column is not in index, try to find it in nodes and insert back into index.
153	    bool tryRestoreColumn(const std::string & column_name);
154	    /// Find column in result. Remove it from index.
155	    /// If columns is in inputs and has no dependent nodes, remove it from inputs too.
156	    /// Return true if column was removed from inputs.
157	    bool removeUnusedResult(const std::string & column_name);
158	
159	    void projectInput(bool project = true) { project_input = project; }
160	    bool isInputProjected() const { return project_input; }
161	    bool isOutputProjected() const { return projected_output; }
162	
163	    void removeUnusedActions(const Names & required_names, bool allow_remove_inputs = true, bool allow_constant_folding = true);
164	    void removeUnusedActions(const NameSet & required_names, bool allow_remove_inputs = true, bool allow_constant_folding = true);
165	
166	    /// Transform the current DAG in a way that leaf nodes get folded into their parents. It's done
167	    /// because each projection can provide some columns as inputs to substitute certain sub-DAGs
168	    /// (expressions). Consider the following example:
169	    /// CREATE TABLE tbl (dt DateTime, val UInt64,
170	    ///                   PROJECTION p_hour (SELECT SUM(val) GROUP BY toStartOfHour(dt)));
171	    ///
172	    /// Query: SELECT toStartOfHour(dt), SUM(val) FROM tbl GROUP BY toStartOfHour(dt);
173	    ///
174	    /// We will have an ActionsDAG like this:
175	    /// FUNCTION: toStartOfHour(dt)       SUM(val)
176	    ///                 ^                   ^
177	    ///                 |                   |
178	    /// INPUT:          dt                  val
179	    ///
180	    /// Now we traverse the DAG and see if any FUNCTION node can be replaced by projection's INPUT node.
181	    /// The result DAG will be:
182	    /// INPUT:  toStartOfHour(dt)       SUM(val)
183	    ///
184	    /// We don't need aggregate columns from projection because they are matched after DAG.
185	    /// Currently we use canonical names of each node to find matches. It can be improved after we
186	    /// have a full-featured name binding system.
187	    ///
188	    /// @param required_columns should contain columns which this DAG is required to produce after folding. It used for result actions.
189	    /// @param projection_block_for_keys contains all key columns of given projection.
190	    /// @param predicate_column_name means we need to produce the predicate column after folding.
191	    /// @param add_missing_keys means whether to add additional missing columns to input nodes from projection key columns directly.
192	    /// @return required columns for this folded DAG. It's expected to be fewer than the original ones if some projection is used.
193	    NameSet foldActionsByProjection(
194	        const NameSet & required_columns,
195	        const Block & projection_block_for_keys,
196	        const String & predicate_column_name = {},
197	        bool add_missing_keys = true);
198	
199	    /// Reorder the index nodes using given position mapping.
200	    void reorderAggregationKeysForProjection(const std::unordered_map<std::string_view, size_t> & key_names_pos_map);
201	
202	    /// Add aggregate columns to index nodes from projection
203	    void addAggregatesViaProjection(const Block & aggregates);
204	
205	    bool hasArrayJoin() const;
206	    bool hasStatefulFunctions() const;
207	    bool trivial() const; /// If actions has no functions or array join.
208	    void assertDeterministic() const; /// Throw if not isDeterministic.
209	
210	#if USE_EMBEDDED_COMPILER
211	    void compileExpressions(size_t min_count_to_compile_expression, const std::unordered_set<const Node *> & lazy_executed_nodes = {});
212	#endif
213	
214	    ActionsDAGPtr clone() const;
215	
216	    /// Execute actions for header. Input block must have empty columns.
217	    /// Result should be equal to the execution of ExpressionActions built from this DAG.
218	    /// Actions are not changed, no expressions are compiled.
219	    ///
220	    /// In addition, check that result constants are constants according to DAG.
221	    /// In case if function return constant, but arguments are not constant, materialize it.
222	    Block updateHeader(Block header) const;
223	
224	    /// For apply materialize() function for every output.
225	    /// Also add aliases so the result names remain unchanged.
226	    void addMaterializingOutputActions();
227	
228	    /// Apply materialize() function to node. Result node has the same name.
229	    const Node & materializeNode(const Node & node);
230	
231	    enum class MatchColumnsMode
232	    {
233	        /// Require same number of columns in source and result. Match columns by corresponding positions, regardless to names.
234	        Position,
235	        /// Find columns in source by their names. Allow excessive columns in source.
236	        Name,
237	    };
238	
239	    /// Create ActionsDAG which converts block structure from source to result.
240	    /// It is needed to convert result from different sources to the same structure, e.g. for UNION query.
241	    /// Conversion should be possible with only usage of CAST function and renames.
242	    /// @param ignore_constant_values - Do not check that constants are same. Use value from result_header.
243	    /// @param add_casted_columns - Create new columns with converted values instead of replacing original.
244	    /// @param new_names - Output parameter for new column names when add_casted_columns is used.
245	    static ActionsDAGPtr makeConvertingActions(
246	        const ColumnsWithTypeAndName & source,
247	        const ColumnsWithTypeAndName & result,
248	        MatchColumnsMode mode,
249	        bool ignore_constant_values = false,
250	        bool add_casted_columns = false,
251	        NameToNameMap * new_names = nullptr);
252	
253	    /// Create expression which add const column and then materialize it.
254	    static ActionsDAGPtr makeAddingColumnActions(ColumnWithTypeAndName column);
255	
256	    /// Create ActionsDAG which represents expression equivalent to applying first and second actions consequently.
257	    /// Is used to replace `(first -> second)` expression chain to single `merge(first, second)` expression.
258	    /// If first.settings.project_input is set, then outputs of `first` must include inputs of `second`.
259	    /// Otherwise, any two actions may be combined.
260	    static ActionsDAGPtr merge(ActionsDAG && first, ActionsDAG && second);
261	
262	    using SplitResult = std::pair<ActionsDAGPtr, ActionsDAGPtr>;
263	
264	    /// Split ActionsDAG into two DAGs, where first part contains all nodes from split_nodes and their children.
265	    /// Execution of first then second parts on block is equivalent to execution of initial DAG.
266	    /// First DAG and initial DAG have equal inputs, second DAG and initial DAG has equal index (outputs).
267	    /// Second DAG inputs may contain less inputs then first DAG (but also include other columns).
268	    SplitResult split(std::unordered_set<const Node *> split_nodes) const;
269	
270	    /// Splits actions into two parts. Returned first half may be swapped with ARRAY JOIN.
271	    SplitResult splitActionsBeforeArrayJoin(const NameSet & array_joined_columns) const;
272	
273	    /// Splits actions into two parts. First part has minimal size sufficient for calculation of column_name.
274	    /// Index of initial actions must contain column_name.
275	    SplitResult splitActionsForFilter(const std::string & column_name) const;
276	
277	    /// Splits actions into two parts. The first part contains all the calculations required to calculate sort_columns.
278	    /// The second contains the rest.
279	    SplitResult splitActionsBySortingDescription(const NameSet & sort_columns) const;
280	
281	    /// Create actions which may calculate part of filter using only available_inputs.
282	    /// If nothing may be calculated, returns nullptr.
283	    /// Otherwise, return actions which inputs are from available_inputs.
284	    /// Returned actions add single column which may be used for filter. Added column will be the first one.
285	    /// Also, replace some nodes of current inputs to constant 1 in case they are filtered.
286	    ///
287	    /// @param all_inputs should contain inputs from previous step, which will be used for result actions.
288	    /// It is expected that all_inputs contain columns from available_inputs.
289	    /// This parameter is needed to enforce result actions save columns order in block.
290	    /// Otherwise for some queries, e.g. with GROUP BY, columns will be mixed.
291	    /// Example: SELECT sum(x), y, z FROM tab WHERE z > 0 and sum(x) > 0
292	    /// Pushed condition: z > 0
293	    /// GROUP BY step will transform columns `x, y, z` -> `sum(x), y, z`
294	    /// If we just add filter step with actions `z -> z > 0` before GROUP BY,
295	    /// columns will be transformed like `x, y, z` -> `z > 0, z, x, y` -(remove filter)-> `z, x, y`.
296	    /// To avoid it, add inputs from `all_inputs` list,
297	    /// so actions `x, y, z -> z > 0, x, y, z` -(remove filter)-> `x, y, z` will not change columns order.
298	    ActionsDAGPtr cloneActionsForFilterPushDown(
299	        const std::string & filter_name,
300	        bool can_remove_filter,
301	        const Names & available_inputs,
302	        const ColumnsWithTypeAndName & all_inputs);
303	
304	private:
305	    Node & addNode(Node node);
306	
307	    void removeUnusedActions(bool allow_remove_inputs = true, bool allow_constant_folding = true);
308	
309	#if USE_EMBEDDED_COMPILER
310	    void compileFunctions(size_t min_count_to_compile_expression, const std::unordered_set<const Node *> & lazy_executed_nodes = {});
311	#endif
312	
313	    static ActionsDAGPtr cloneActionsForConjunction(NodeRawConstPtrs conjunction, const ColumnsWithTypeAndName & all_inputs);
314	};
